{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Add a masked-position pairwise ranking term using the existing unobserved negatives, alongside full-catalog cross-entropy in each category’s single BERT4Rec model.",
      "edits": [
        {
          "find": "    return torch.nn.functional.cross_entropy(logits, targets, reduction=\"mean\")",
          "replace": "    ce_loss = torch.nn.functional.cross_entropy(logits, targets, reduction=\"mean\")\n    positive_scores = logits.gather(1, targets.unsqueeze(1)).squeeze(1)\n    negative_targets = neg[mask] - 1\n    negative_scores = logits.gather(1, negative_targets.unsqueeze(1)).squeeze(1)\n    ranking_loss = torch.nn.functional.softplus(negative_scores - positive_scores).mean()\n    return ce_loss + 0.1 * ranking_loss"
        }
      ]
    },
    {
      "category": "feature_construction",
      "rationale": "Mildly emphasize rare visible context items using training-only frequency statistics. Store input scales in each checkpoint; the generated predictor imports this model class and restores the same buffer. Padding and mask vectors remain unchanged.",
      "edits": [
        {
          "find": "        self.mask_token = itemnum + 1\n        self.item_emb = nn.Embedding(itemnum + 2, hidden_units, padding_idx=0)",
          "replace": "        self.mask_token = itemnum + 1\n        self.register_buffer(\"item_input_scale\", torch.ones(itemnum + 2))\n        self.item_emb = nn.Embedding(itemnum + 2, hidden_units, padding_idx=0)"
        },
        {
          "find": "        x = item_vectors * (self.hidden_units ** 0.5) + self.pos_emb(pos)",
          "replace": "        item_vectors = item_vectors * self.item_input_scale[seq].unsqueeze(-1)\n        x = item_vectors * (self.hidden_units ** 0.5) + self.pos_emb(pos)"
        },
        {
          "find": "    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)",
          "replace": "    training_counts = np.bincount(\n        np.fromiter(\n            (item for history in user_train.values() for item in history),\n            dtype=np.int64,\n        ),\n        minlength=itemnum + 2,\n    )\n    with torch.no_grad():\n        log_counts = torch.as_tensor(\n            np.log1p(training_counts[1:itemnum + 1]),\n            dtype=model.item_input_scale.dtype,\n            device=device,\n        )\n        count_mean = log_counts.mean()\n        count_std = log_counts.std(unbiased=False).clamp_min(1e-6)\n        model.item_input_scale[1:itemnum + 1].copy_(\n            1.0 + 0.03 * torch.tanh((count_mean - log_counts) / count_std)\n        )\n    optimizer = torch.optim.Adam(model.parameters(), lr=LR, weight_decay=WEIGHT_DECAY)"
        }
      ]
    }
  ],
  "change_summary": "Across all four datasets, combine checkpointed rarity-based input scaling with CE plus a 0.1-weighted pairwise ranking loss. Preserve masked training, appended-mask inference, backbone, hyperparameters and one checkpoint per category."
}
